package com.integration.service.solar.impl;

import com.integration.model.APILogger;
import com.integration.repository.APILoggerRepository;
import com.integration.repository.*;
import com.integration.service.solar.SolarLeadSquaredService;
import com.integration.util.RestUtils;
import com.integration.util.Utils;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;

import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;

@Service
@Log4j2
public class SolarLeadSquaredServiceImpl implements SolarLeadSquaredService {

    @Autowired
    RestUtils restUtils;

    @Value("${lsq.lead.url:https://api-in21.leadsquared.com/v2/ProspectManagement.svc/Prospect.RetrieveByGuid}")
    String lsqLeadUrl;

    @Value("${lsq.update.lead.url:https://api-in21.leadsquared.com/v2/LeadManagement.svc/Lead.Update}")
    String lsqUpdateLeadUrl;

    @Value("${lsq.recently.modified.url:https://api-in21.leadsquared.com/v2/LeadManagement.svc/Leads.RecentlyModified}")
    String lsqRecentlyModifiedUrl;

    @Value("${lsq.leads.get.url}")
    String lsqLeadsGetUrl;

    @Value("${lsq.bulk.update.lead.url}")
    String lsqBulkUpdateLeadUrl;

    @Value("${lsq.bulk.update.lead.v2.url}")
    String lsqBulkUpdateLeadV2Url;

    @Value("${lsq.leads.get_by_ids.url}")
    String lsqLeadsGetByIdsUrl;

    @Autowired
    private APILoggerRepository apiLoggerRepository;

    @Value("${solar.lsq.secretKey}")
    String solarLsqSecretKey;

    @Value("${solar.lsq.accessKey}")
    String solarLsqAccessKey;

    @Override
    public Map<String, String> createHeaders() {
        Map<String, String> headers = new HashMap<>();
        headers.put("x-LSQ-AccessKey", solarLsqAccessKey);
        headers.put("x-LSQ-SecretKey", solarLsqSecretKey);
        return headers;
    }

    private void logApiCall(String api, String url, String request, String response, String status, String service) {
        try {
            APILogger logger = new APILogger();
            logger.setApi(api);
            logger.setUrl(url);
            logger.setRequest(request);
            logger.setResponse(response);
            logger.setStatus(status);
            logger.setService(service);
            logger.setDateCreated(new Date());
            logger.setHit(1);
            apiLoggerRepository.save(logger);
        } catch (Exception e) {
            e.printStackTrace();
            log.error("Failed to log API call to database", e);
        }
    }

    @Override
    public Map<String, Object> getLeadDetails(String leadId) throws Exception {
        String url = lsqLeadUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey + "&prospectId=" + leadId;
        log.info("Fetching lead details from LeadSquared for Lead ID: " + leadId);

        ResponseEntity<Map> response = restUtils.get(url);

        logApiCall("Get Lead Details", url, "", response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            List<Map<String, Object>> bodyList = (List<Map<String, Object>>) response.getBody();
            if (bodyList != null && !bodyList.isEmpty()) {
                Map<String, Object> leadData = bodyList.get(0);
                Map<String, Object> sapPayload = new HashMap<>();

                sapPayload.put("Name", leadData.get("FirstName") + " " + (leadData.get("LastName") != null ? leadData.get("LastName") : ""));
                sapPayload.put("MobileNumber", leadData.get("Phone"));
                sapPayload.put("PAN", leadData.get("mx_PAN_Number"));
                sapPayload.put("Email", leadData.get("EmailAddress"));
                sapPayload.put("Address", leadData.get("AddressAddressLine1"));
                sapPayload.put("PinCode", leadData.get("mx_ZipCode"));
                sapPayload.put("State", leadData.get("mx_State"));
                sapPayload.put("City", leadData.get("mx_City"));
                sapPayload.put("PlantCode", leadData.get("mx_Plant_Code"));
                sapPayload.put("MaterialCode", leadData.get("mx_Material_Code"));
                sapPayload.put("SystemType", leadData.get("mx_System_Type"));
                sapPayload.put("StructureHeight", leadData.get("mx_Structure_Height"));
                sapPayload.put("TotalConversionAmount", leadData.get("mx_Total_Conversion_Amount"));
                sapPayload.put("ProductAmount", leadData.get("mx_Product_Amount"));
                sapPayload.put("ServiceAmount", leadData.get("mx_Service_Amount"));

                log.info("Successfully fetched and mapped lead details for SAP: " + sapPayload);
                return sapPayload;
            }
        }
        log.error("Failed to fetch lead details for Lead ID: " + leadId + ". Response: " + response);
        return null;
    }

    @Override
    public boolean updateLeadSapCode(String leadId, String sapCode) throws Exception {
        String url = lsqUpdateLeadUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey + "&leadId=" + leadId + "&postUpdatedLead=true";
        log.info("Updating Lead in LeadSquared for Lead ID: " + leadId + " with SAP Code: " + sapCode);

        List<Map<String, String>> payload = new ArrayList<>();
        Map<String, String> attribute = new HashMap<>();
        attribute.put("Attribute", "mx_Customer_Code");
        attribute.put("Value", sapCode);
        payload.add(attribute);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonBody = mapper.writeValueAsString(payload);

        HttpEntity<String> entity = new HttpEntity<>(jsonBody, headers);
        ResponseEntity<Map> response = restUtils.post(url, entity);

        logApiCall("Update Lead SAP Code", url, jsonBody, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode().is2xxSuccessful()) {
            log.info("Successfully updated lead in LeadSquared. Response: " + response.getBody());
            return true;
        } else {
            log.error("Failed to update lead in LeadSquared. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return false;
        }
    }

    @Override
    public ResponseEntity<Object> getLeadsByStage() throws Exception {
        String url = lsqLeadsGetUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        String payload = createLeadByStagePayload();
        Map<String, String> headers = createHeaders();
        ResponseEntity<Object> response = restUtils.postV3(url, payload, headers);
        logApiCall("Leads.Get", url, payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }

    private String createLeadByStagePayload(){
        String payload = "{\n" +
                "    \"Parameter\": {\n" +
                "        \"LookupName\": \"ProspectStage\",\n" +
                "        \"LookupValue\": \"Deal Converted\",\n" +
                "        \"SqlOperator\": \"=\"\n" +
                "    },\n" +
                "    \"Columns\": {\n" +
                "        \"Include_CSV\": \"ProspectID, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"\n" +
                "    },\n" +
                "    \"Sorting\": {\n" +
                "        \"ColumnName\": \"CreatedOn\",\n" +
                "        \"Direction\": \"1\"\n" +
                "    },\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": 1,\n" +
                "        \"PageSize\": 100\n" +
                "    }\n" +
                "}";
        return payload;
    }

    @Override
    public ResponseEntity<Object> getLeadsByStagePaginated(String payload) throws Exception {
        String url = lsqLeadsGetUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        Map<String, String> headers = createHeaders();
        ResponseEntity<Object> response = restUtils.postV3(url, payload, headers);
        logApiCall("Leads.Get", url, payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }

    private String createRecentlyModifiedLeadsPayload(int pageIndex, int pageSize, String fromDateString, String toDateString){
        String jsonBody = "{\n" +
                "\t\"Parameter\": {\n" +
                "        \"FromDate\": \"" + fromDateString + "\",\n" +
                "        \"ToDate\": \"" + toDateString + "\"\n" +
                "    },\n" +
                "    \"Columns\":{\"Include_CSV\":\"ProspectID, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"},\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": " + pageIndex + ",\n" +
                "        \"PageSize\":  " + pageSize + "\n" +
                "    }\n" +
                "}";
        return jsonBody;
    }

    @Override
    public List<Map<String, Object>> getRecentlyModifiedLeads(Date fromDate, Date toDate) throws Exception {
        String fromDateString = Utils.formatDate(fromDate, "yyyy-MM-dd HH:mm:ss");
        String toDateString = Utils.formatDate(toDate, "yyyy-MM-dd HH:mm:ss");
        int pageIndex = 1;
        int pageSize = 500;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;

        String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        log.info("Fetching recently modified leads from LeadSquared from " + fromDate + " to " + toDate);

        DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        //String fromDateString = dateFormat.format(fromDate);
        //String toDateString = dateFormat.format(toDate);

        logApiCall("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
            Object responseBody = response.getBody();
            if (responseBody instanceof List) {
                return (List<Map<String, Object>>) responseBody;
            } else if (responseBody instanceof Map) {
                Map<String, Object> bodyMap = (Map<String, Object>) responseBody;
                if (bodyMap.containsKey("Leads")) {
                    return (List<Map<String, Object>>) bodyMap.get("Leads");
                }
            }
            log.warn("Unexpected response format for recently modified leads. Response body: " + responseBody);
            return null;
        } else {
            log.error("Failed to fetch recently modified leads from LeadSquared. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return null;
        }
    }

    @Override
    public ResponseEntity<Map> getRecentlyModifiedLeadsByPayload(String body) throws Exception {
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        logApiCall("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        return response;
    }

    @Override
    public boolean updateLeadsInBulk(Map<String, Object> payload) throws Exception {
        String url = lsqBulkUpdateLeadUrl; //+ "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        System.out.println("Updating leads in bulk in LeadSquared with payload: " + payload);

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonPayload = mapper.writeValueAsString(payload);

        ResponseEntity<Map> response = restUtils.postV2(url, jsonPayload, createHeaders());

        logApiCall("Update Leads In Bulk", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && body.get("Status").toString().equalsIgnoreCase("Success")) {
                log.info("Successfully updated leads in bulk.");
                return true;
            }
        }
        log.error("Failed to update leads in bulk. Response: " + response);
        return false;
    }

    @Override
    public boolean updateLeadsInBulkV2(Map<String, Object> payload) throws Exception {
        String url = lsqBulkUpdateLeadV2Url;
        log.info("Updating leads in bulk (v2) in LeadSquared with " + (payload != null ? payload.size() : 0) + " records");

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonPayload = mapper.writeValueAsString(payload);
        ResponseEntity<Map> response = restUtils.postV2(url, jsonPayload, createHeaders());

        logApiCall("Update Leads In Bulk V2", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && ((Map)body.get("Status")).get("Message")!=null && ((Map)body.get("Status")).get("Message").toString().equalsIgnoreCase("Processed")) {
                log.info("Successfully updated leads in bulk (v2).");
                return true;
            }
        }
        log.error("Failed to update leads in bulk (v2). Response: " + response);
        return false;
    }

    private String createLeadsBulkByIdsPayload(List<String> leadIds) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("  \"SearchParameters\": {\n");
        sb.append("    \"LeadIds\": [\n");
        for (int i = 0; i < leadIds.size(); i++) {
            sb.append("      \"").append(leadIds.get(i)).append("\"");
            if (i < leadIds.size() - 1) {
                sb.append(",");
            }
            sb.append("\n");
        }
        sb.append("    ]\n");
        sb.append("  },\n");
        sb.append("  \"Columns\": {\n");
        sb.append("    \"Include_CSV\": \"ProspectID, ProspectStage, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code\"\n");
        sb.append("  },\n");
        sb.append("  \"Paging\": {\n");
        sb.append("    \"PageIndex\": 1,\n");
        sb.append("    \"PageSize\": 1000\n");
        sb.append("  }\n");
        sb.append("}");
        return sb.toString();
    }

    @Override
    public ResponseEntity<Map> getLeadsInBulkByIds(List<String> leadIds) throws Exception {
        String url = lsqLeadsGetByIdsUrl;
        String payload = createLeadsBulkByIdsPayload(leadIds);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(url, payload, headers);
        logApiCall("Get Leads In Bulk By IDs", url, payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }
