package com.integration.service.impl;

import com.integration.model.APILogger;
import com.integration.model.leadsquared.*;
import com.integration.repository.*;
import com.integration.service.LeadSquaredService;
import com.integration.service.RazorPayService;
import com.integration.util.RestUtils;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;

import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;

@Service
@Log4j2
public class LeadSquaredServiceImpl implements LeadSquaredService {

    @Autowired
    LsqOwnerRepository lsqOwnerRepository;

    @Autowired
    LsqRazorpayRepository lsqRazorpayRepository;

    @Autowired
    LeadsquaredUserRepository leadsquaredUserRepository;

    @Autowired
    LsqPaymentLinkRepository lsqPaymentLinkRepository;

    @Autowired
    RestUtils restUtils;

    @Autowired
    APILoggerRepository apiLoggerRepository;

    @Value("${lsq.activity.url}")
    String lsqActivityUrl;

    @Value("${lsq.secretKey}")
    String lsqSecretKey;

    @Value("${lsq.accessKey}")
    String lsqAccessKey;

    @Value("${lsq.owners.url}")
    String lsqOwnersUrl;

    @Value("${lsq.lead.get_by_id.url}")
    String lsqGetLeadByIdUrl;
    @Autowired
    private RazorPayService razorPayService;

    public boolean processLsqRazorpayActivity(Date fromDate, Date toDate) throws Exception {
        String fetchActivitiesUrl = lsqActivityUrl;
        Map<String, String> headers = createHeaders();
        DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String fromDateString = dateFormat.format(fromDate);
        String toDateString = dateFormat.format(toDate);
        int pageIndex = 1;
        int pageSize = 500;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        String prospectActivityId = null;
        while (processedRecords < totalRecords) {
            try {
                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, "214");

                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);

                try{
                    logApiCall("Razorpay Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                }catch (Exception e){
                    e.printStackTrace();
                }
                Map<String, Object> responseBody = r.getBody();

                totalRecords = (int) responseBody.get("RecordCount");

                if (responseBody != null) {
                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get("List");
                    if (activityList != null) {
                        for (Map<String, Object> activity : activityList) {
                            try {
                                processedRecords++;
                                prospectActivityId = (String) activity.get("ProspectActivityId");
                                LsqRazorpayActivity lsqRazorpayActivity = lsqRazorpayRepository.findByProspectActivityId(prospectActivityId);
                                if(lsqRazorpayActivity==null){
                                    lsqRazorpayActivity = new LsqRazorpayActivity();
                                    lsqRazorpayActivity.setProspectActivityId(prospectActivityId);
                                }
                                lsqRazorpayActivity.setActivityEvent("214");
                                lsqRazorpayActivity.setActivityEventName("Payment Paid");
                                lsqRazorpayActivity.setDisplayName("Razorpay");
                                lsqRazorpayActivity.setActivityEventNote((String) activity.get("ActivityEvent_Note"));

                                String relatedProspectId = (String) activity.get("RelatedProspectId");

                                LeadsquaredUser leadsquaredUser = fetchLeadDetails(relatedProspectId);

                                if(leadsquaredUser!=null){

                                    lsqRazorpayActivity.setCustomerName(leadsquaredUser.getFirstName() + " " + leadsquaredUser.getLastName());
                                    lsqRazorpayActivity.setCustomerMobile(leadsquaredUser.getMobile());

                                    lsqRazorpayActivity.setRelatedProspectId(relatedProspectId);

                                    String owner = getLeadOwner((String) activity.get("Owner"));
                                    lsqRazorpayActivity.setOwner(owner);


                                    String status = (String) activity.get("mx_Custom_16");
                                    lsqRazorpayActivity.setPaymentStatus(status);

                                    lsqRazorpayActivity.setEvent((String) activity.get("mx_Custom_1"));

                                    Object amountObj = activity.get("mx_Custom_2");
                                    Integer amount = amountObj != null ? Integer.parseInt(amountObj.toString()) : null;
                                    lsqRazorpayActivity.setAmount(amount);

                                    String paymentId = (String) activity.get("mx_Custom_3");
                                    if(paymentId!=null && paymentId.length()>0){
                                        try{
                                            Map<String, String> payeeDetails = razorPayService.fetchPayeeDetails(paymentId);
                                            if(payeeDetails!=null && payeeDetails.get("payeeMobileNumber")!=null && payeeDetails.get("payeeMobileNumber").length()>0){
                                                lsqRazorpayActivity.setCustomerPaymentMobile(payeeDetails.get("payeeMobileNumber"));
                                            }
                                        }catch (Exception e){
                                            e.printStackTrace();
                                        }
                                    }
                                    lsqRazorpayActivity.setPaymentId(paymentId);
                                    lsqRazorpayActivity.setOrderId((String) activity.get("mx_Custom_4"));
                                    lsqRazorpayActivity.setUpiTransactionId((String) activity.get("mx_Custom_5"));
                                    lsqRazorpayActivity.setBankTransactionId((String) activity.get("mx_Custom_6"));
                                    lsqRazorpayActivity.setPaymentMethod((String) activity.get("mx_Custom_11"));
                                    lsqRazorpayActivity.setVirtualPrivateAddress((String) activity.get("mx_Custom_12"));

                                    Object taxObj = activity.get("mx_Custom_13");
                                    Integer tax = taxObj != null ? Integer.parseInt(taxObj.toString()) : null;
                                    lsqRazorpayActivity.setTax(tax);

                                    lsqRazorpayActivity.setPaymentStatus((String) activity.get("mx_Custom_16"));

                                    Object paymentTimeObj = activity.get("mx_Custom_17");
                                    Date paymentTime = null;
                                    if (paymentTimeObj != null) {
                                        paymentTime = dateFormat.parse(paymentTimeObj.toString());
                                    }
                                    lsqRazorpayActivity.setPaymentTime(paymentTime);
                                    lsqRazorpayRepository.save(lsqRazorpayActivity);
                                }

                            } catch (Exception exc) {
                                exc.printStackTrace();
                                log.error("Some exception occurred while processing Lsq Razorpay Activity " + prospectActivityId);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                ex.printStackTrace();
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

            System.out.println("fetching " + processedRecords + "out of" + totalRecords);
            pageIndex++;
        }
        return success;
    }

    public boolean processLsqOwners() throws Exception {
        boolean success = true;

        try{
            String url = getUrl(lsqOwnersUrl);
            ResponseEntity<Object> r = restUtils.get(url);
            Object responseBody = r.getBody();
            if (responseBody != null) {
                List<Map> ownerList = (List<Map>) responseBody;
                if (ownerList != null) {
                    for (Map owner : ownerList) {
                        try{
                            int statusCode = (int)owner.get("StatusCode");
                            if(statusCode==0){
                                LsqOwner lsqOwner = new LsqOwner();
                                lsqOwner.setOwnerId((String)owner.get("ID"));
                                lsqOwner.setEmailAddress((String)owner.get("EmailAddress"));
                                lsqOwner.setRole((String)owner.get("Role"));
                                lsqOwner.setFirstName((String)owner.get("FirstName"));
                                lsqOwner.setLastName((String)owner.get("LastName"));
                                lsqOwner.setDateCreated(new Date());
                                lsqOwnerRepository.save(lsqOwner);
                            }
                        }catch (Exception ee){
                            ee.printStackTrace();
                            log.error("Some exception occurred while processing owner");
                        }
                    }
                }
            }
        }catch (Exception e){
            e.printStackTrace();
            log.error("Some exception occurred while fetching lead owners ",e);
            success = false;
        }
        return success;
    }

    @Override
    public ResponseEntity<Object> fetchLeadById(String leadId) throws Exception {
        String url = getUrl(lsqGetLeadByIdUrl) + "&id=" + leadId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");
        ResponseEntity responseEntity = restUtils.get(url, headers);

        try {
            if (responseEntity.getStatusCode() == HttpStatus.OK && responseEntity.getBody() != null) {
                List<Map<String, Object>> responseList = (List<Map<String, Object>>) responseEntity.getBody();
                if (responseList != null && !responseList.isEmpty()) {
                    Map<String, Object> leadData = responseList.get(0);
                    String prospectId = (String) leadData.get("ProspectID");

                    Optional<LeadsquaredUser> existingUser = leadsquaredUserRepository.findById(prospectId);
                    if (!existingUser.isPresent()) {
                        LeadsquaredUser newUser = new LeadsquaredUser();
                        newUser.setProspectId(prospectId);
                        newUser.setOwner((String) leadData.get("OwnerIdName"));
                        String firstName = leadData.get("FirstName") != null ? (String) leadData.get("FirstName") : "";
                        String lastName = leadData.get("LastName") != null ? (String) leadData.get("LastName") : "";
                        newUser.setFirstName((firstName).trim());
                        newUser.setLastName((lastName).trim());
                        newUser.setMobile((String) leadData.get("Phone"));

                        String createdOnStr = (String) leadData.get("CreatedOn");
                        if (createdOnStr != null) {
                            DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
                            newUser.setCreatedOn(dateFormat.parse(createdOnStr));
                        }

                        leadsquaredUserRepository.save(newUser);
                        log.info("Saved new LeadsquaredUser for leadId: " + leadId);
                    } else {
                        log.info("LeadsquaredUser already exists for leadId: " + leadId);
                    }
                }
            }
        } catch (Exception e) {
            log.error("Error while processing LeadsquaredUser for leadId: " + leadId, e);
        }

        return responseEntity;
    }

    String getUrl(String url){
        if(url!=null){
            url+="?accessKey="+lsqAccessKey+"&secretKey="+lsqSecretKey;
        }
        return url;
    }

    public String getLeadOwner(String leadId){
        LsqOwner leadOwnerDocument = lsqOwnerRepository.findByOwnerId(leadId);
        String leadEmail = null;
        if (leadOwnerDocument!=null){
            leadEmail = leadOwnerDocument.getEmailAddress();
        }
        else {
            leadEmail = leadId;
        }
        return leadEmail;
    }

    private String createActivityPayload(int pageIndex, int pageSize, String fromDateString, String toDateString, String activityId) {
        String payload = "{\n" +
                "\"Parameter\": {\n" +
                "\"FromDate\": \"" + fromDateString + "\",\n" +
                "\"ToDate\": \"" + toDateString + "\",\n" +
