package com.integration.service.impl;

import com.integration.model.APILogger;
import com.integration.model.solar.DistrictPlantCodeMapping;
import com.integration.model.solar.StateCodeMapping;
import com.integration.repository.APILoggerRepository;
import com.integration.repository.solar.DistrictPlantCodeMappingRepository;
import com.integration.repository.solar.StateCodeMappingRepository;
import com.integration.service.SapService;
import com.integration.util.RestUtils;
import com.integration.util.Utils;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import java.util.HashMap;
import java.util.Map;

@Service
@Log4j2
public class SapServiceImpl implements SapService {

    @Value("${sap.api.url:https://poprd.sar-group.com/RESTAdapter/CustomerMaster_ESB}")
    private String sapApiUrl;

    @Value("${sap.api.authorization:Basic VlVENTY4MDY3OkBnOU80NS01}")
    private String sapAuthorization;

    @Autowired
    private RestUtils restUtils;

    @Autowired
    private APILoggerRepository apiLoggerRepository;

    @Autowired
    private StateCodeMappingRepository stateCodeMappingRepository;

    @Autowired
    private DistrictPlantCodeMappingRepository districtPlantCodeMappingRepository;

    private Map<String, Object> createPayload(Map<String, Object> leadData) throws Exception {
        Map<String, Object> record = new HashMap<>();
        record.put("Dist_Channel", "16");
        record.put("Divison", 16);

        Map<String, Object> generalData = new HashMap<>();
        generalData.put("SAPCustomerID", ""); // Should be empty for new customer creation or as per logic
        generalData.put("Title", "");
        generalData.put("firstName", leadData.getOrDefault("Name", ""));
        generalData.put("lastName", "");
        String mobile = Utils.transformMobileNumber(leadData.getOrDefault("Mobile", "").toString());
        generalData.put("mobile", mobile);
        generalData.put("username", leadData.getOrDefault("Email", ""));
        generalData.put("address", leadData.getOrDefault("Address", ""));
        generalData.put("pinCode", leadData.getOrDefault("Pincode", ""));
        generalData.put("city", leadData.getOrDefault("City", ""));

        //Map<String, String> stateData = Utils.getStateMapping();
        //String stateCode = stateData.getOrDefault(leadData.getOrDefault("State", "").toString(), "");
        String stateCode = getStateCode(leadData.getOrDefault("State", "").toString());
        generalData.put("state", stateCode);
        generalData.put("country", "IN");
        generalData.put("GSTN", leadData.getOrDefault("PAN", ""));
        generalData.put("BU_SORT1_TXT", "SOLAR360");

        record.put("General_Data", generalData);

        Map<String, Object> companyCodeData = new HashMap<>();
        companyCodeData.put("Recon_acc", "104100006");
        companyCodeData.put("Payment_terms", "Z001");
        record.put("Company_code_Data", companyCodeData);

        Map<String, Object> salesAreaData = new HashMap<>();
        salesAreaData.put("customer_type_c", "DZ");

        String plantCode = getPlantCode(leadData.getOrDefault("City", "").toString());
        salesAreaData.put("plant", plantCode);
        record.put("Sales_Area_Data", salesAreaData);

        Map<String, Object> payload = new HashMap<>();
        payload.put("Record", record);
        return payload;
    }
    @Override
    public Map<String, Object> createCustomer(Map<String, Object> leadData) throws Exception {
        log.info("Creating customer in SAP with lead data: " + leadData);

        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", sapAuthorization);
        Map<String, Object> payload = createPayload(leadData);

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonBody = mapper.writeValueAsString(payload);

        Map<String, Object> responseBody = null;
        String statusCode = "";
        try{
            ResponseEntity<Map> response = restUtils.postV2(sapApiUrl, jsonBody, headers);
            statusCode = String.valueOf(response.getStatusCodeValue());
            if (response.getStatusCode().is2xxSuccessful()) {
                log.info("Successfully created customer in SAP. Response: " + response.getBody());
                responseBody = response.getBody();
            }
        }catch (Exception e){
            e.printStackTrace();
        }
        String logResponse = responseBody != null ? responseBody.toString() : "";
        logApiCall("Create Customer", sapApiUrl, jsonBody, logResponse, statusCode, "SAP");
        return responseBody;
    }

    private void logApiCall(String api, String url, String request, String response, String status, String service) {
        try {
            APILogger logger = new APILogger();
            logger.setApi(api);
            logger.setUrl(url);
            logger.setRequest(request);
            logger.setResponse(response);
            logger.setStatus(status);
            logger.setService(service);
            logger.setDateCreated(new java.util.Date());
            logger.setHit(1);
            apiLoggerRepository.save(logger);
        } catch (Exception e) {
            log.error("Failed to log API call to database", e);
        }
    }

    @Override
    public String getStateCode(String state) throws Exception {
        String stateCode = "";
        StateCodeMapping stateCodeMapping = stateCodeMappingRepository.findByStateIgnoreCase(state);
        if(stateCodeMapping!=null){
            stateCode = stateCodeMapping.getStateCode();
        }
        return stateCode;
    }

    @Override
    public String getPlantCode(String district) throws Exception {
        String plantCode = "";
        DistrictPlantCodeMapping plantCodeMapping = districtPlantCodeMappingRepository.findByDistrictIgnoreCase(district);
        if(plantCodeMapping!=null){
            plantCode = plantCodeMapping.getPlantCode();
        }
        return plantCode;
    }
}

