package com.integration.controller.solar;

import com.integration.service.solar.SolarLeadService;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@Log4j2
@RequestMapping("/leads")
@RequiredArgsConstructor
public class SolarLeadController {

    @Autowired
    SolarLeadService solarLeadService;

    @GetMapping(value = "/runLeadWorkflowDateWise")
    public Object runLeadWorkflow(@RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date fromDate,
