        generalData.put("country", "IN");
        generalData.put("GSTN", leadData.getOrDefault("PAN", ""));
        generalData.put("BU_SORT1_TXT", "SOLAR360");

        record.put("General_Data", generalData);

        Map<String, Object> companyCodeData = new HashMap<>();
        companyCodeData.put("Recon_acc", "104100006");
        companyCodeData.put("Payment_terms", "Z001");
        record.put("Company_code_Data", companyCodeData);

        Map<String, Object> salesAreaData = new HashMap<>();
        salesAreaData.put("customer_type_c", "DZ");

        String plantCode = getPlantCode(leadData.getOrDefault("City", "").toString());
        salesAreaData.put("plant", plantCode);
        record.put("Sales_Area_Data", salesAreaData);

        Map<String, Object> payload = new HashMap<>();
        payload.put("Record", record);
        return payload;
    }
    @Override
    public Map<String, Object> createCustomer(Map<String, Object> leadData) throws Exception {
        log.info("Creating customer in SAP with lead data: " + leadData);

        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", sapAuthorization);
        Map<String, Object> payload = createPayload(leadData);

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonBody = mapper.writeValueAsString(payload);

        Map<String, Object> responseBody = null;
        String statusCode = "";
        try{
            ResponseEntity<Map> response = restUtils.postV2(sapApiUrl, jsonBody, headers);
            statusCode = String.valueOf(response.getStatusCodeValue());
            if (response.getStatusCode().is2xxSuccessful()) {
                log.info("Successfully created customer in SAP. Response: " + response.getBody());
                responseBody = response.getBody();
            }
        }catch (Exception e){
            e.printStackTrace();
        }
        String logResponse = responseBody != null ? responseBody.toString() : "";
        logApiCall("Create Customer", sapApiUrl, jsonBody, logResponse, statusCode, "SAP");
        return responseBody;
    }

    private void logApiCall(String api, String url, String request, String response, String status, String service) {
        try {
            APILogger logger = new APILogger();
            logger.setApi(api);
            logger.setUrl(url);
            logger.setRequest(request);
            logger.setResponse(response);
            logger.setStatus(status);
            logger.setService(service);
            logger.setDateCreated(new java.util.Date());
            logger.setHit(1);
            apiLoggerRepository.save(logger);
        } catch (Exception e) {
            log.error("Failed to log API call to database", e);
        }
    }

    @Override
    public String getStateCode(String state) throws Exception {
        String stateCode = "";
        StateCodeMapping stateCodeMapping = stateCodeMappingRepository.findByStateIgnoreCase(state);
        if(stateCodeMapping!=null){
            stateCode = stateCodeMapping.getStateCode();
        }
        return stateCode;
    }

    @Override
    public String getPlantCode(String district) throws Exception {
        String plantCode = "";
        DistrictPlantCodeMapping plantCodeMapping = districtPlantCodeMappingRepository.findByDistrictIgnoreCase(district);
        if(plantCodeMapping!=null){
            plantCode = plantCodeMapping.getPlantCode();
        }
        return plantCode;
    }
}

