            try {
                dateFormat.setTimeZone(TimeZone.getTimeZone("IST"));
                formattedDate = dateFormat.format(date);
            } catch (Exception e) {
                log.error("Some exception occurred while formatting the date ", e);
            }
        }
        return formattedDate;
    }

    public static Map getRelevantDates(String jobType, LocalDate ytdDate) throws ParseException {
        Map<String, Date> dateMap = new HashMap<>();
        LocalDate now = LocalDate.now();
        Date endDate = Date.from(Instant.now());
        if (jobType != null && jobType.contains("month")) {
            LocalDate startLocalDate = now.withDayOfMonth(1);
            Date startDate = Date.from(startLocalDate.atStartOfDay(ZoneId.systemDefault()).toInstant());
            dateMap.put("startDate", startDate);
            dateMap.put("endDate", endDate);
        } else if (jobType != null && jobType.contains("year")) {
//            LocalDate startLocalDate = LocalDate.of(2024,10,1);
            try {
                if (ytdDate != null) {
                    Date startDate = Date.from(ytdDate.atStartOfDay(ZoneId.systemDefault()).toInstant());
                    dateMap.put("startDate", startDate);
                    dateMap.put("endDate", endDate);
                }
            } catch (Exception e) {
                e.printStackTrace();
                log.error("Some exception occurred while setting start date and end date when jobType contains year ", e);
            }
        } else if (jobType != null && (jobType.contains("offerreport") || jobType.contains("consolidatedofferreport"))) {
            //LocalDate startLocalDate = now.withDayOfMonth(1);
            LocalDate startLocalDate = LocalDate.of(2022, Month.JANUARY, 1);
            Date startDate = Date.from(startLocalDate.atStartOfDay(ZoneId.systemDefault()).toInstant());
            dateMap.put("startDate", startDate);
            dateMap.put("endDate", endDate);
        }
        return dateMap;
    }
}

