package com.integration.service;

import com.integration.model.ScheduleConfig;
import com.integration.model.ServiceLog;
import com.integration.repository.ServiceLogRepository;
import com.integration.service.solar.SolarLeadService;
import com.integration.util.Utils;
import lombok.extern.log4j.Log4j2;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.TaskScheduler;
import org.springframework.scheduling.annotation.SchedulingConfigurer;
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;
import org.springframework.scheduling.config.ScheduledTaskRegistrar;
import org.springframework.scheduling.support.CronTrigger;
import org.springframework.stereotype.Service;

import javax.annotation.PostConstruct;
import java.util.*;
import java.util.concurrent.ScheduledFuture;

@Service
@Log4j2
public class ExternalScheduler implements SchedulingConfigurer {

    private static Logger LOGGER = LoggerFactory.getLogger(ExternalScheduler.class);

    ScheduledTaskRegistrar scheduledTaskRegistrar;

    @Autowired
    TaskScheduler taskScheduler;

    @Autowired
    ScheduleConfigService scheduleConfigService;

    @Autowired
    ServiceLogRepository serviceLogRepository;

    @Autowired
    LeadSquaredService leadSquaredService;

    @Autowired
    SolarLeadService solarLeadService;

    @Autowired
    RazorPayService razorPayService;

    Map<String, ScheduledFuture> futureMap = new HashMap<>();

    @PostConstruct
    public void loadJobs(){
        if(scheduledTaskRegistrar == null){
            scheduledTaskRegistrar = new ScheduledTaskRegistrar();
        }
        if(taskScheduler == null){
            ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
            scheduler.setThreadNamePrefix("ThreadPoolTaskScheduler");
            scheduler.setPoolSize(1);
            scheduler.initialize();
            taskScheduler = scheduler;
        }
        scheduledTaskRegistrar.setScheduler(taskScheduler);
        log.info("Load Jobs");
        List<ScheduleConfig> scheduleConfigList = scheduleConfigService.findActiveConfigs();
        scheduleConfigList.forEach(scheduleConfig -> {
            addJob(scheduleConfig.getConfigKey(),scheduleConfig.getConfigValue());
        });
    }

    /*@Bean
    public TaskScheduler poolScheduler() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setThreadNamePrefix("ThreadPoolTaskScheduler");
        scheduler.setPoolSize(1);
        scheduler.initialize();
        return scheduler;
    }*/

    // Initially scheduler has no job
    @Override
    public void configureTasks(ScheduledTaskRegistrar taskRegistrar) {
        if (scheduledTaskRegistrar == null) {
            scheduledTaskRegistrar = taskRegistrar;
        }

        if (taskRegistrar.getScheduler() == null) {
            taskRegistrar.setScheduler(taskScheduler);
        }
    }

    public boolean addJob(String jobName, String cronExpression) {
        if (futureMap.containsKey(jobName)) {
            return false;
        }
        CronTrigger croneTrigger = new CronTrigger(cronExpression, TimeZone.getTimeZone("Asia/Kolkata"));
        /*ScheduledFuture future = scheduledTaskRegistrar.getScheduler().schedule(() -> taskToBeExecuted(""), t -> {
            Calendar nextExecutionTime = new GregorianCalendar();
            Date lastActualExecutionTime = t.lastActualExecutionTime();
            nextExecutionTime.setTime(lastActualExecutionTime != null ? lastActualExecutionTime : new Date());
            nextExecutionTime.add(Calendar.SECOND, 5);
            return nextExecutionTime.getTime();
        });*/
        ScheduledFuture future = scheduledTaskRegistrar.getScheduler().schedule(() -> {
            try {
                taskToBeExecuted(jobName);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }, croneTrigger);
        configureTasks(scheduledTaskRegistrar);
        futureMap.put(jobName, future);
        return true;
    }

    public boolean removeJob(String name) {
        if (!futureMap.containsKey(name)) {
            return false;
        }
        ScheduledFuture future = futureMap.get(name);
        future.cancel(true);
        futureMap.remove(name);
        return true;
    }

    public void taskToBeExecuted(String methodName) throws Exception {

        if (methodName.equals("lsqLeadOwners_job")) {
            LOGGER.info(methodName + "Job running");
            leadSquaredService.processLsqOwners();
            LOGGER.info(methodName + " Job End.");
        }

        if (methodName.equals("lead_workflow_job")) {
            LOGGER.info(methodName + " Job Running. Scheduled every 3 hours.");
            runLeadWorkflow();
            LOGGER.info(methodName + " Job End.");
        }

        if(methodName.equals("lsqRazorpayActivity_job")){
            LOGGER.info(methodName+" Job Running.");
            processLsqRazorpayActivity();
            LOGGER.info(methodName + " Job End.");
        }

        if(methodName.equals("razorpaySettlement_job")){
            LOGGER.info(methodName+" Job Running.");
            fetchRazorpaySettlement();
            LOGGER.info(methodName + " Job End.");
        }
    }

    public void updateServiceLog(String serviceName, String status, Date successDate){
        try{
            ServiceLog serviceLog = serviceLogRepository.findByServiceName(serviceName);
            if(serviceLog==null){
                serviceLog = new ServiceLog();
            }
            serviceLog.setServiceName(serviceName);
            serviceLog.setLastTry(new Date());
            serviceLog.setStatus(status);
            if(successDate!=null){
                serviceLog.setLastSuccessRun(successDate);
            }
            serviceLogRepository.save(serviceLog);
        }catch(Exception e){
            e.printStackTrace();
            log.error("Error in Saving Service Log ",e);
        }
    }

    private void runLeadWorkflow() {
        Date fromDate = null;
        ServiceLog serviceLog = serviceLogRepository.findByServiceName("lead_workflow_job");
        if(serviceLog!=null){
            fromDate = serviceLog.getLastSuccessRun();
        }else{
            fromDate = new Date(System.currentTimeMillis()- 2*60*60*1000);
        }
        Date toDate = new Date();
        try {
            boolean success = solarLeadService.processLeads(fromDate,toDate);
            if(success){
                updateServiceLog("lead_workflow_job","Success",new Date());
            }else{
                updateServiceLog("lead_workflow_job","Fail",null);
            }
        } catch (Exception e) {
            updateServiceLog("lead_workflow_job", "Fail", null);
            log.error("Error in lead_workflow_job: ", e);
        }
    }

    private void processLsqRazorpayActivity() throws Exception {
        Date fromDate = null;
        ServiceLog serviceLog = serviceLogRepository.findByServiceName("lsqRazorpayActivity");
        if(serviceLog!=null){
            fromDate = serviceLog.getLastSuccessRun();
        }
        if(fromDate == null){
            fromDate = new Date(System.currentTimeMillis() - 48*60*60*1000);
        }
        Date toDate = new Date();
        try {
            boolean success = leadSquaredService.processLsqRazorpayActivity(fromDate,toDate);
            if(success){
                updateServiceLog("lsqRazorpayActivity","Success",new Date());
            }else{
                updateServiceLog("lsqRazorpayActivity","Fail",null);
            }
        } catch (Exception e) {
            updateServiceLog("lsqRazorpayActivity", "Fail", null);
            log.error("Error in lsqRazorpayActivity_job: ", e);
        }
    }

    private void fetchRazorpaySettlement() throws Exception {
        Date fromDate = null;
        ServiceLog serviceLog = serviceLogRepository.findByServiceName("razorpaySettlement");
        if (serviceLog != null) {
            fromDate = serviceLog.getLastSuccessRun();
        }
        if (fromDate == null) {
            fromDate = new Date(System.currentTimeMillis() - 48 * 60 * 60 * 1000);
        }

        try {
            Map<String, String> dateParts = Utils.getDateParts(fromDate);
            boolean success = razorPayService.getSettlementsReconCombined(dateParts.get("year"), dateParts.get("month"), dateParts.get("day"));
            if (success) {
                updateServiceLog("razorpaySettlement", "Success", new Date());
            } else {
                updateServiceLog("razorpaySettlement", "Fail", null);
            }
        } catch (Exception e) {
            updateServiceLog("razorpaySettlement", "Fail", null);
            log.error("Error in razorpaySettlement_job: ", e);
        }
    }
}

