                                    String prospectID = null;
                                    String prospectStage = null;
                                    String customerCode = null;
                                    //String mobile = null;
                                    String name = null;
                                    String email = null;
                                    String address = null;
                                    String city = null;
                                    String state = null;
                                    String pincode = null;
                                    String pan = null;
                                    for(Map<String, Object> leadProperty : leadProperties){
                                        //if(leadProperty.containsKey("Attribute") && leadProperty.containsKey("Value")){

                                        if(leadProperty.get("Attribute").equals("ProspectID")){
                                            prospectID = (leadProperty.get("Value")!=null)?leadProperty.get("Value").toString():"";
                                        }
                                        if(leadProperty.get("Attribute").equals("ProspectStage")){
                                            prospectStage = (leadProperty.get("Value")!=null)?leadProperty.get("Value").toString():"";
                                        }
                                        if(leadProperty.get("Attribute").equals("mx_Customer_Code")){
                                            customerCode = (leadProperty.get("Value")!=null)?leadProperty.get("Value").toString():"";
                                        }

                                        if(prospectID!=null && !prospectID.isEmpty() && prospectStage!=null && !prospectStage.isEmpty() && prospectStage.equals("Deal Converted") && (customerCode==null || customerCode.isEmpty())){
                                            leadData = new HashMap<>();

                                            leadData.put("ProspectID", prospectID);
                                            if(leadProperty.get("Attribute").equals("FirstName")){
                                                name = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Name", name);

                                            if(leadProperty.get("Attribute").equals("Phone")){
                                                phone = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Mobile", phone);

                                            if(leadProperty.get("Attribute").equals("mx_PAN_No")){
                                                pan = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("PAN", pan);

                                            if(leadProperty.get("Attribute").equals("EmailAddress")){
                                                email = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Email", email);

                                            if(leadProperty.get("Attribute").equals("mx_Street1")){
                                                address = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Address", address);

                                            if(leadProperty.get("Attribute").equals("mx_City")){
                                                city = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("City", city);

                                            if(leadProperty.get("Attribute").equals("mx_States")){
                                                state = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("State", state);

                                            if(leadProperty.get("Attribute").equals("mx_Zip")){
                                                pincode = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Pincode", pincode);
                                        }
                                        //}
                                    }
                                    System.out.println("leadData = " + leadData);
                                    if(leadData!=null){
                                        Map<String, Object> sapResponseBody = sapService.createCustomer(leadData);
                                        if (sapResponseBody != null) {
                                            Map<String, String> sapCustomer = prepareDataMap(leadData, sapResponseBody);
                                            if(sapCustomer!=null && sapCustomer.get("prospectId")!=null && !sapCustomer.get("prospectId").isEmpty() && sapCustomer.get("sapCustomerCode")!=null && !sapCustomer.get("sapCustomerCode").isEmpty()){
                                                updateLeadInLeadsquared(sapCustomer);
                                            }
                                        }
                                    }
                                }catch(Exception e){
                                    e.printStackTrace();
                                    log.error("Process Leads Error while creating SAP Customer for lead with mobile number: "+phone);
                                }
                                success = true;
                            }
                            if (leads.isEmpty()) {
                                processedRecords = totalRecords;
                            }
                        }
                    }
                } else {
                    processedRecords = totalRecords;
                }
            }catch (Exception ee){
                success = false;
                ee.printStackTrace();
                log.error("Some exception occurred while processing leads batch for SAP Customer Creation",ee);
            }
            System.out.println("fetching " + processedRecords + " out of " + totalRecords);
            pageIndex++;
        }
        return success;
    }

