    private Map<String, String> prepareDataMap(Map<String, Object> leadData, Map<String, Object> responseMap) {
        Map<String, String> sapCustomer = null;
        if(responseMap!=null && responseMap.get("status")!=null && responseMap.get("status").equals(0)){
            Map<String, String> record = responseMap.get("Record") != null ? (Map) responseMap.get("Record") : null;
            if(record.get("Change_Number")!=null){
                sapCustomer = new HashMap<>();
                String sapCustomerCode = record.get("Change_Number");
                sapCustomer.put("sapCustomerCode", sapCustomerCode);
                sapCustomer.put("mobile", leadData.get("Mobile").toString());
                sapCustomer.put("prospectId", leadData.get("ProspectID").toString());
            }
        }
        return sapCustomer;
    }

    private void updateLeadInLeadsquared(Map<String, String> sapCustomer){
        if(sapCustomer!=null && sapCustomer.get("prospectId")!=null && !sapCustomer.get("prospectId").isEmpty() && sapCustomer.get("sapCustomerCode")!=null && !sapCustomer.get("sapCustomerCode").isEmpty()){
            log.info("Updating lead {} in LeadSquared with SAP code {}", sapCustomer.get("prospectId"), sapCustomer.get("sapCustomerCode"));
            try {
                solarLeadSquaredService.updateLeadSapCode(sapCustomer.get("prospectId"),sapCustomer.get("sapCustomerCode"));
            } catch (Exception e) {
                log.error("Error updating lead {} in LeadSquared", sapCustomer.get("prospectId"), e);
            }
        }
    }

    private void sendBatchToLeadsquared(List<Map<String, String>> batch) {
        if (batch == null || batch.isEmpty()) {
            return;
        }
        try {
            Map<String, Object> leadPayload = prepareLeadUpdateData(batch);
            log.info("Updating {} leads in bulk in LeadSquared", batch.size());
            solarLeadSquaredService.updateLeadsInBulkV2(leadPayload);
        } catch (Exception e) {
            log.error("Error while updating leads in bulk", e);
        }
    }

    private Map<String, Object> prepareLeadUpdateData(List<Map<String, String>> sapCustomerList) {
        Map<String, Object> leadUpdate = new HashMap<>();
        leadUpdate.put("SearchByKey", "ProspectId");

        /*Map<String, Object> options = new HashMap<>();
        options.put("PushNonExistentLeadsToUnProcessedList", false);
        leadUpdate.put("Options", options);*/

        List<Map<String, Object>> leadPropertiesList = new ArrayList<>();
        for (Map<String,String> sapCustomer : sapCustomerList){
            Map<String, Object> leadPropertyEntry = new HashMap<>();
            List<Map<String, String>> fields = new ArrayList<>();

            Map<String, String> emailField = new HashMap<>();
            emailField.put("Attribute", "ProspectID");
            emailField.put("Value", sapCustomer.get("prospectId"));
            fields.add(emailField);

            Map<String, String> customerCodeField = new HashMap<>();
            customerCodeField.put("Attribute", "mx_Customer_Code");
            customerCodeField.put("Value", sapCustomer.get("customerCode"));
            fields.add(customerCodeField);

            leadPropertyEntry.put("Fields", fields);
            leadPropertiesList.add(leadPropertyEntry);
        }
        leadUpdate.put("LeadPropertiesList", leadPropertiesList);
        return leadUpdate;
    }

