                                    leadData.put("Email", lead.get("EmailAddress"));
                                }
                                if(lead.get("mx_Street1")!=null){
                                    leadData.put("Address", lead.get("mx_Street1"));
                                }
                                if(lead.get("mx_City")!=null){
                                    leadData.put("City", lead.get("mx_City"));
                                }
                                if(lead.get("mx_States")!=null){
                                    leadData.put("State", lead.get("mx_States"));
                                }
                                if(lead.get("mx_Zip")!=null){
                                    leadData.put("Pincode", lead.get("mx_Zip"));
                                }

                                System.out.println("leadData = " + leadData);
                                if(leadData!=null){
                                    Map<String, Object> sapResponseBody = sapService.createCustomer(leadData);
                                    if (sapResponseBody != null) {
                                        Map<String, String> sapCustomer = prepareDataMap(leadData, sapResponseBody);
                                        if(sapCustomer!=null && sapCustomer.get("prospectId")!=null && !sapCustomer.get("prospectId").isEmpty() && sapCustomer.get("sapCustomerCode")!=null && !sapCustomer.get("sapCustomerCode").isEmpty()){
                                            updateLeadInLeadsquared(sapCustomer);
                                        }
                                    }
                                }
                            }
                        }catch(Exception e){
                            e.printStackTrace();
                            log.error("Process LeadIds Error while creating SAP Customer for lead with mobile number: "+lead.get("Phone"));
                        }
                    }
                }else {
                    success = false;
                }
            }
        }else{
            success = false;
        }
        return success;
    }
}

