    18→
    19→@Service
    20→@Log4j2
    21→public class LivsolServiceImpl implements LivsolService {
    22→
    23→    @Autowired
    24→    private RestUtils restUtils;
    25→
    26→    @Autowired
    27→    private APILoggerRepository apiLoggerRepository;
    28→
    29→    @Value("${livsol.api.url}")
    30→    private String livsolApiUrl;
    31→
    32→    @Value("${livsol.api.key}")
    33→    private String livsolApiKey;
    34→
    35→    @Override
    36→    public Map<String, Object> pushLeadDetails(Map<String, Object> leadData) throws Exception {
    37→        log.info("Pushing lead details to Livsol API: " + leadData);
    38→
    39→        HttpHeaders headers = new HttpHeaders();
    40→        headers.setContentType(MediaType.APPLICATION_JSON);
    41→        headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
    42→        headers.set("X-API-KEY", livsolApiKey);
    43→
    44→        // Ensure sapCustomerCode is present as requested
    45→        if (!leadData.containsKey("sapCustomerCode")) {
    46→            log.warn("sapCustomerCode is missing in the lead data. Adding a default/placeholder value.");
    47→            leadData.put("sapCustomerCode", "DEFAULT_SAP_CODE");
    48→        }
    49→
    50→        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    51→        String jsonBody = mapper.writeValueAsString(leadData);
    52→
    53→        HttpEntity<String> entity = new HttpEntity<>(jsonBody, headers);
    54→        log.info("Livsol Request URL: " + livsolApiUrl);
    55→        log.info("Livsol Request Payload: " + jsonBody);
    56→
    57→        ResponseEntity<Map> response = restUtils.post(livsolApiUrl, entity);
    58→
    59→        logApiCall("Push Lead", livsolApiUrl, jsonBody, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "Livsol");
    60→
    61→        if (response.getStatusCode().is2xxSuccessful()) {
    62→            log.info("Successfully pushed lead details to Livsol. Response: " + response.getBody());
    63→            return response.getBody();
    64→        } else {
    65→            log.error("Failed to push lead details to Livsol. Status: " + response.getStatusCode() + " Response: " + response.getBody());
    66→            return response.getBody();
    67→        }
    68→    }
    69→
    70→    private void logApiCall(String api, String url, String request, String response, String status, String service) {
    71→        try {
    72→            APILogger logger = new APILogger();
    73→            logger.setApi(api);
    74→            logger.setUrl(url);
    75→            logger.setRequest(request);
    76→            logger.setResponse(response);
    77→            logger.setStatus(status);
    78→            logger.setService(service);
    79→            logger.setDateCreated(new java.util.Date());
    80→            logger.setHit(1);
    81→            apiLoggerRepository.save(logger);
    82→        } catch (Exception e) {
    83→            log.error("Failed to log API call to database", e);
    84→        }
    85→    }
    86→}
