    18→
    19→    private static final String API_KEY_HEADER = "X-API-Key";
    20→
    21→    @Value("${api.key}")
    22→    private String validApiKey;
    23→
    24→    @Override
    25→    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
    26→                                    FilterChain filterChain) throws ServletException, IOException {
    27→        String providedKey = request.getHeader(API_KEY_HEADER);
    28→        if (validApiKey.equals(providedKey)) {
    29→            filterChain.doFilter(request, response);
    30→        } else {
    31→            log.warn("Unauthorized request to {} — invalid or missing API key", request.getRequestURI());
    32→            response.setStatus(HttpStatus.UNAUTHORIZED.value());
    33→            response.getWriter().write("Unauthorized");
    34→        }
    35→    }
    36→
    37→    @Override
    38→    protected boolean shouldNotFilter(HttpServletRequest request) {
    39→        String path = request.getRequestURI();
    40→        return path.startsWith("/webhook/");
    41→    }
    42→}
