package com.integration.util;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.RestTemplate;

import java.util.Collections;
import java.util.List;
import java.util.Map;

public class RestUtils {

    @Autowired
    RestTemplate restTemplate;
    public ResponseEntity get(String url){
        ResponseEntity<Object> response = restTemplate.getForEntity(url, Object.class);
        return response ;
    }

    public ResponseEntity get(String url, Map<String, String> headers) {
        HttpHeaders httpHeaders = new HttpHeaders();
        httpHeaders.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
        headers.forEach(httpHeaders::add);
        HttpEntity<String> entity = new HttpEntity<>(httpHeaders);
        return restTemplate.exchange(url, org.springframework.http.HttpMethod.GET, entity, Object.class);
    }

    public ResponseEntity post(String url, HttpEntity<String> entity){
        ResponseEntity<Map> response = restTemplate.postForEntity(url,entity,Map.class);
        return response;
    }

    public ResponseEntity postV2(String url, String body, Map<String, String> headers){
        HttpHeaders httpHeaders = new HttpHeaders();
        httpHeaders.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
        httpHeaders.setContentType(MediaType.APPLICATION_JSON);
        headers.forEach((k,v) -> httpHeaders.add(k,v));
        HttpEntity<String> entity = new HttpEntity<>(body, httpHeaders);
        ResponseEntity<Map> response = restTemplate.postForEntity(url,entity,Map.class);
        return response;
    }

    public ResponseEntity postV3(String url, String body, Map<String, String> headers){
        HttpHeaders httpHeaders = new HttpHeaders();
        httpHeaders.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
        httpHeaders.setContentType(MediaType.APPLICATION_JSON);
        headers.forEach((k,v) -> httpHeaders.add(k,v));
        HttpEntity<String> entity = new HttpEntity<>(body, httpHeaders);
        ResponseEntity<Object> response = restTemplate.postForEntity(url,entity,Object.class);
        return response;
    }
}

