import org.springframework.data.mongodb.core.query.Query;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.mail.javamail.MimeMessageHelper;
import org.springframework.stereotype.Service;

import javax.mail.MessagingException;
import javax.mail.internet.MimeMessage;
import java.util.*;

@Service
@Log4j2
public class EmailServiceImpl implements EmailService {

    @Autowired
    JavaMailSender mailSender;

    @Autowired
    MongoTemplate mongoTemplate;

    @Value("${app.mail.from}")
    private String fromMailId;

    @Override
    //public void sendMail(String subject, String from, List<String> recipients, String text) throws MessagingException {
    public void sendMail(Map<String, Object> mailData) throws MessagingException {
        List<String> recipients = (List<String>)mailData.get("recipients");
        String text = (String)mailData.get("text");
        String from = (String)mailData.get("from");
        String subject = (String)mailData.get("subject");
        if(recipients!=null && text!=null && from!=null && subject!=null){
            String[] addresses = recipients.stream().toArray(String[]::new);
            MimeMessage mimeMessage = mailSender.createMimeMessage();
            MimeMessageHelper helper = new MimeMessageHelper(mimeMessage, "utf-8");
            helper.setText(text,true);
            helper.setFrom(from);
            helper.setTo(addresses);
            helper.setSubject(subject);
            try {
                mailSender.send(mimeMessage);
            }catch (Exception ex) {
                log.error("Some exception occurred while sending the mail ",ex);
            }
        }
    }

