                    "<br><p>"+awsPath+"</p><br><p></p><p>Thanks</p><p>Admin CRM|LocktheDeal</p>";
            mailData.put("from",from);
            mailData.put("subject",subject);
            mailData.put("recipients",recipients);
            mailData.put("text",text);
