                                            leadData.put("State", state);

                                            if(leadProperty.get("Attribute").equals("mx_Zip")){
                                                pincode = (String)leadProperty.getOrDefault("Value","");
                                            }
                                            leadData.put("Pincode", pincode);
                                        }
                                        //}
                                    }
                                    log.debug("leadData = {}", leadData);
                                    if(leadData!=null){
                                        Map<String, Object> sapResponseBody = sapService.createCustomer(leadData);
                                        if (sapResponseBody != null) {
                                            Map<String, String> sapCustomer = prepareDataMap(leadData, sapResponseBody);
                                            if(sapCustomer!=null && sapCustomer.get("prospectId")!=null && !sapCustomer.get("prospectId").isEmpty() && sapCustomer.get("sapCustomerCode")!=null && !sapCustomer.get("sapCustomerCode").isEmpty()){
                                                sapCustomerBatch.add(sapCustomer);
                                                if(sapCustomerBatch.size() >= 25){
                                                    sendBatchToLeadsquared(sapCustomerBatch);
                                                    sapCustomerBatch.clear();
                                                }
                                            }
                                        }
                                    }
                                }catch(Exception e){
                                    log.error("Bulk Leads Error while creating SAP Customer for lead with mobile number: " + phone, e);
                                }
                                success = true;
                            }
                            if (leads.isEmpty()) {
                                processedRecords = totalRecords;
                            }
                        }
                    }
                } else {
                    processedRecords = totalRecords;
                }
            }catch (Exception ee){
                success = false;
                log.error("Some exception occurred while processing leads batch for SAP Customer Creation",ee);
            }
            log.info("processLeadsBulk: fetching {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        if(!sapCustomerBatch.isEmpty()){
            sendBatchToLeadsquared(sapCustomerBatch);
            sapCustomerBatch.clear();
        }
        return success;
    }

    @Override
    public void updateLeadInBulk(List<Map<String, String>> sapCustomerList){
        sendBatchToLeadsquared(sapCustomerList);
    }

    @Override
    public boolean processLeadIds(List<String> leadIds) throws Exception {
        ResponseEntity<Map> response = solarLeadSquaredService.getLeadsInBulkByIds(leadIds);
        boolean success = true;
        if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
            Map<String, Object> responseBody = response.getBody();
            if(responseBody!=null){
                Map<String, Object> bodyMap = responseBody;
                if (bodyMap.containsKey("Leads")) {
                    List<Map<String, Object>> leads = (List<Map<String, Object>>) bodyMap.get("Leads");
                    for(Map<String, Object> lead : leads) {
                        String prospectStage = "Deal Converted";//(String)lead.getOrDefault("ProspectStage", "");
                        String customerCode = (String)lead.getOrDefault("mx_Customer_Code","");
                        try{
                            if(prospectStage!=null && !prospectStage.isEmpty() && prospectStage.equals("Deal Converted") && (customerCode==null || customerCode.isEmpty())){
                                Map<String, Object> leadData = new HashMap<>();
                                if(lead.get("ProspectID")!=null){
                                    leadData.put("ProspectID", lead.get("ProspectID"));
                                }
                                if(lead.get("FirstName")!=null){
                                    leadData.put("Name", lead.get("FirstName"));
                                }
                                if(lead.get("Phone")!=null){
                                    leadData.put("Mobile", lead.get("Phone"));
                                }
                                if(lead.get("mx_PAN_No")!=null){
                                    leadData.put("PAN", lead.get("mx_PAN_No"));
                                }
                                if(lead.get("EmailAddress")!=null){
                                    leadData.put("Email", lead.get("EmailAddress"));
                                }
                                if(lead.get("mx_Street1")!=null){
                                    leadData.put("Address", lead.get("mx_Street1"));
                                }
                                if(lead.get("mx_City")!=null){
                                    leadData.put("City", lead.get("mx_City"));
                                }
                                if(lead.get("mx_States")!=null){
                                    leadData.put("State", lead.get("mx_States"));
                                }
                                if(lead.get("mx_Zip")!=null){
                                    leadData.put("Pincode", lead.get("mx_Zip"));
                                }

                                log.debug("leadData = {}", leadData);
                                if(leadData!=null){
                                    Map<String, Object> sapResponseBody = sapService.createCustomer(leadData);
                                    if (sapResponseBody != null) {
                                        Map<String, String> sapCustomer = prepareDataMap(leadData, sapResponseBody);
                                        if(sapCustomer!=null && sapCustomer.get("prospectId")!=null && !sapCustomer.get("prospectId").isEmpty() && sapCustomer.get("sapCustomerCode")!=null && !sapCustomer.get("sapCustomerCode").isEmpty()){
                                            updateLeadInLeadsquared(sapCustomer);
                                        }
                                    }
                                }
                            }
                        }catch(Exception e){
                            log.error("Process LeadIds Error while creating SAP Customer for lead with mobile number: " + lead.get("Phone"), e);
                        }
                    }
                }else {
                    success = false;
                }
            }
        }else{
            success = false;
        }
        return success;
    }
}

