package com.integration.service.impl;

import com.integration.model.dto.MailRequest;
import com.integration.service.EmailService;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.bson.Document;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.mail.javamail.MimeMessageHelper;
import org.springframework.stereotype.Service;

import javax.mail.MessagingException;
import javax.mail.internet.MimeMessage;
import java.util.ArrayList;
import java.util.List;

@Service
@Log4j2
@RequiredArgsConstructor
public class EmailServiceImpl implements EmailService {

    private final JavaMailSender mailSender;
    private final MongoTemplate mongoTemplate;

    @Value("${app.mail.from}")
    private String fromMailId;

    @Override
    public void sendMail(MailRequest mailRequest) throws MessagingException {
        if (mailRequest.getRecipients() == null || mailRequest.getText() == null
                || mailRequest.getFrom() == null || mailRequest.getSubject() == null) {
            return;
        }
        String[] addresses = mailRequest.getRecipients().toArray(new String[0]);
        MimeMessage mimeMessage = mailSender.createMimeMessage();
        MimeMessageHelper helper = new MimeMessageHelper(mimeMessage, "utf-8");
        helper.setText(mailRequest.getText(), true);
        helper.setFrom(mailRequest.getFrom());
        helper.setTo(addresses);
        helper.setSubject(mailRequest.getSubject());
        try {
            mailSender.send(mimeMessage);
        } catch (Exception ex) {
            log.error("Some exception occurred while sending the mail", ex);
        }
    }

    @Override
    public MailRequest mailData(String jobType, String awsPath, String date) {
        String from = fromMailId;
        String subject;
        String mailType;
        String bodyLabel;

        if (jobType != null && jobType.contains("year")) {
            subject = "New - Order Report YTD V2.0" + date;
            mailType = "Yearly Report";
            bodyLabel = "YTD order report V2.0";
        } else {
            subject = "New - Order Report MTD[All Status] V2.0" + date;
            mailType = "Monthly Report";
            bodyLabel = "MTD order[All Status] report V2.0";
        }

        Query query = new Query();
        query.addCriteria(Criteria.where("typesOfMail").is(mailType));
        query.addCriteria(Criteria.where("active").is(true));
        List<Document> recipientList = mongoTemplate.find(query, Document.class, "reportRecipient");
        List<String> recipients = new ArrayList<>();
        recipientList.forEach(email -> recipients.add(email.getString("recipientMail")));

        String text = "<p>Hi All</p><br><p>PFA " + bodyLabel + " dated on " + date + "</p>"
                + "<p></p><p>Please click the below Link : <br><p>" + awsPath
                + "</p><br><p></p><p>Thanks</p><p>Admin CRM|LocktheDeal</p>";

        return MailRequest.builder()
                .from(from)
                .subject(subject)
                .recipients(recipients)
                .text(text)
                .build();
    }
}

