package com.integration.service.solar.impl;

import com.integration.model.dto.LeadSapRequest;
import com.integration.model.dto.SapCreateResponse;
import com.integration.service.SapService;
import com.integration.service.solar.SolarLeadService;
import com.integration.service.solar.SolarLeadSquaredService;
import com.integration.util.Utils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;

import java.util.*;

@Service
@Log4j2
@RequiredArgsConstructor
public class SolarLeadServiceImpl implements SolarLeadService {

    private final SolarLeadSquaredService solarLeadSquaredService;
    private final SapService sapService;

    private String createRecentlyModifiedLeadsPayload(int pageIndex, int pageSize, String fromDateString, String toDateString) {
        return "{\n" +
                "\t\"Parameter\": {\n" +
                "        \"FromDate\": \"" + fromDateString + "\",\n" +
                "        \"ToDate\": \"" + toDateString + "\"\n" +
                "    },\n" +
                "    \"Columns\":{\"Include_CSV\":\"ProspectID, ProspectStage, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"},\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": " + pageIndex + ",\n" +
                "        \"PageSize\":  " + pageSize + "\n" +
                "    }\n" +
                "}";
    }

    @Override
    public SapCreateResponse createSapCustomer() throws Exception {
        LeadSapRequest request = LeadSapRequest.builder()
                .name("DifferentName")
                .pan("ABCDE1234A")
                .address("SP")
                .city("Fazilka")
                .state("Punjab")
                .pincode("152116")
                .email("SP@SP.com")
                .prospectId("lsq-1234")
                .build();
        return sapService.createCustomer(request);
    }

    private void updateLeadInLeadsquared(String prospectId, String sapCustomerCode) {
        if (prospectId == null || prospectId.isEmpty() || sapCustomerCode == null || sapCustomerCode.isEmpty()) {
            return;
        }
        log.info("Updating lead {} in LeadSquared with SAP code {}", prospectId, sapCustomerCode);
        try {
            solarLeadSquaredService.updateLeadSapCode(prospectId, sapCustomerCode);
        } catch (Exception e) {
            log.error("Error updating lead {} in LeadSquared", prospectId, e);
        }
    }

    private void sendBatchToLeadsquared(List<Map<String, String>> batch) {
        if (batch == null || batch.isEmpty()) {
            return;
        }
        try {
            Map<String, Object> leadPayload = prepareLeadUpdateData(batch);
            log.info("Updating {} leads in bulk in LeadSquared", batch.size());
            solarLeadSquaredService.updateLeadsInBulkV2(leadPayload);
        } catch (Exception e) {
            log.error("Error while updating leads in bulk", e);
        }
    }

    private Map<String, Object> prepareLeadUpdateData(List<Map<String, String>> sapCustomerList) {
        Map<String, Object> leadUpdate = new HashMap<>();
        leadUpdate.put("SearchByKey", "ProspectId");

        List<Map<String, Object>> leadPropertiesList = new ArrayList<>();
        for (Map<String, String> sapCustomer : sapCustomerList) {
            Map<String, Object> leadPropertyEntry = new HashMap<>();
            List<Map<String, String>> fields = new ArrayList<>();

            Map<String, String> prospectIdField = new HashMap<>();
            prospectIdField.put("Attribute", "ProspectID");
            prospectIdField.put("Value", sapCustomer.get("prospectId"));
            fields.add(prospectIdField);

            Map<String, String> customerCodeField = new HashMap<>();
            customerCodeField.put("Attribute", "mx_Customer_Code");
            customerCodeField.put("Value", sapCustomer.get("customerCode"));
            fields.add(customerCodeField);

            leadPropertyEntry.put("Fields", fields);
            leadPropertiesList.add(leadPropertyEntry);
        }
        leadUpdate.put("LeadPropertiesList", leadPropertiesList);
        return leadUpdate;
    }

    @Override
    public boolean processLeads(Date fromDate, Date toDate) throws Exception {
        log.info("processLeads fromDate={}, toDate={}", fromDate, toDate);
        String fromDateString = Utils.formatDateWithTimezone(fromDate, "yyyy-MM-dd HH:mm:ss");
        String toDateString = Utils.formatDateWithTimezone(toDate, "yyyy-MM-dd HH:mm:ss");
        log.info("processLeads fromDateString={}, toDateString={}", fromDateString, toDateString);

        int pageIndex = 1;
        int processedRecords = 0;
        int pageSize = 30;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;

        while (processedRecords < totalRecords) {
            try {
                String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
                ResponseEntity<Map> response = solarLeadSquaredService.getRecentlyModifiedLeadsByPayload(body);

                if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                    Map<String, Object> responseBody = response.getBody();
                    totalRecords = (int) responseBody.get("RecordCount");
                    if (responseBody.containsKey("Leads")) {
                        List<Map<String, Object>> leads = (List<Map<String, Object>>) responseBody.get("Leads");
                        for (Map<String, Object> lead : leads) {
                            String phone = "";
                            try {
                                processedRecords++;
                                String prospectID = null;
                                String prospectStage = null;
                                String customerCode = null;
                                String name = null;
                                String email = null;
                                String address = null;
                                String city = null;
                                String state = null;
                                String pincode = null;
                                String pan = null;

                                List<Map<String, Object>> leadProperties = (List<Map<String, Object>>) lead.get("LeadPropertyList");
                                for (Map<String, Object> leadProperty : leadProperties) {
                                    String attr = leadProperty.get("Attribute").toString();
                                    String val = leadProperty.get("Value") != null ? leadProperty.get("Value").toString() : "";

                                    if (attr.equals("ProspectID")) prospectID = val;
                                    if (attr.equals("ProspectStage")) prospectStage = val;
                                    if (attr.equals("mx_Customer_Code")) customerCode = val;
                                    if (attr.equals("FirstName")) name = val;
                                    if (attr.equals("Phone")) { phone = val; }
                                    if (attr.equals("mx_PAN_No")) pan = val;
                                    if (attr.equals("EmailAddress")) email = val;
                                    if (attr.equals("mx_Street1")) address = val;
                                    if (attr.equals("mx_City")) city = val;
                                    if (attr.equals("mx_States")) state = val;
                                    if (attr.equals("mx_Zip")) pincode = val;
                                }

                                if (prospectID != null && !prospectID.isEmpty()
                                        && "Deal Converted".equals(prospectStage)
                                        && (customerCode == null || customerCode.isEmpty())) {

                                    LeadSapRequest request = LeadSapRequest.builder()
                                            .prospectId(prospectID).name(name).mobile(phone)
                                            .pan(pan).email(email).address(address)
                                            .city(city).state(state).pincode(pincode)
                                            .build();
                                    log.debug("processLeads leadData: {}", request);
                                    SapCreateResponse sapResponse = sapService.createCustomer(request);
                                    if (sapResponse != null && sapResponse.getChangeNumber() != null) {
                                        updateLeadInLeadsquared(prospectID, sapResponse.getChangeNumber());
                                    }
                                }
                            } catch (Exception e) {
                                log.error("processLeads error creating SAP customer for lead with mobile: {}", phone, e);
                            }
                            success = true;
                        }
                        if (leads.isEmpty()) processedRecords = totalRecords;
                    }
                } else {
                    processedRecords = totalRecords;
                }
            } catch (Exception ee) {
                success = false;
                log.error("processLeads exception in batch", ee);
            }
            log.info("processLeads: fetching {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    @Override
    public boolean processLeadsBulk(Date fromDate, Date toDate) throws Exception {
        log.info("processLeadsBulk fromDate={}, toDate={}", fromDate, toDate);
        String fromDateString = Utils.formatDateWithTimezone(fromDate, "yyyy-MM-dd HH:mm:ss");
        String toDateString = Utils.formatDateWithTimezone(toDate, "yyyy-MM-dd HH:mm:ss");
        log.info("processLeadsBulk fromDateString={}, toDateString={}", fromDateString, toDateString);

        int pageIndex = 1;
        int processedRecords = 0;
        int pageSize = 30;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        List<Map<String, String>> sapCustomerBatch = new ArrayList<>();

        while (processedRecords < totalRecords) {
            try {
                String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
                ResponseEntity<Map> response = solarLeadSquaredService.getRecentlyModifiedLeadsByPayload(body);

                if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                    Map<String, Object> responseBody = response.getBody();
                    totalRecords = (int) responseBody.get("RecordCount");
                    if (responseBody.containsKey("Leads")) {
                        List<Map<String, Object>> leads = (List<Map<String, Object>>) responseBody.get("Leads");
                        for (Map<String, Object> lead : leads) {
                            String phone = "";
                            try {
                                processedRecords++;
                                String prospectID = null;
                                String prospectStage = null;
                                String customerCode = null;
                                String name = null;
                                String email = null;
                                String address = null;
                                String city = null;
                                String state = null;
                                String pincode = null;
                                String pan = null;

                                List<Map<String, Object>> leadProperties = (List<Map<String, Object>>) lead.get("LeadPropertyList");
                                for (Map<String, Object> leadProperty : leadProperties) {
                                    String attr = leadProperty.get("Attribute").toString();
                                    String val = leadProperty.get("Value") != null ? leadProperty.get("Value").toString() : "";

                                    if (attr.equals("ProspectID")) prospectID = val;
                                    if (attr.equals("ProspectStage")) prospectStage = val;
                                    if (attr.equals("mx_Customer_Code")) customerCode = val;
                                    if (attr.equals("FirstName")) name = val;
                                    if (attr.equals("Phone")) { phone = val; }
                                    if (attr.equals("mx_PAN_No")) pan = val;
                                    if (attr.equals("EmailAddress")) email = val;
                                    if (attr.equals("mx_Street1")) address = val;
                                    if (attr.equals("mx_City")) city = val;
                                    if (attr.equals("mx_States")) state = val;
                                    if (attr.equals("mx_Zip")) pincode = val;
                                }

                                if (prospectID != null && !prospectID.isEmpty()
                                        && "Deal Converted".equals(prospectStage)
                                        && (customerCode == null || customerCode.isEmpty())) {

                                    LeadSapRequest request = LeadSapRequest.builder()
                                            .prospectId(prospectID).name(name).mobile(phone)
                                            .pan(pan).email(email).address(address)
                                            .city(city).state(state).pincode(pincode)
                                            .build();
                                    log.debug("processLeadsBulk leadData: {}", request);
                                    SapCreateResponse sapResponse = sapService.createCustomer(request);
                                    if (sapResponse != null && sapResponse.getChangeNumber() != null) {
                                        Map<String, String> sapCustomer = new HashMap<>();
                                        sapCustomer.put("prospectId", prospectID);
                                        sapCustomer.put("sapCustomerCode", sapResponse.getChangeNumber());
                                        sapCustomerBatch.add(sapCustomer);
                                        if (sapCustomerBatch.size() >= 25) {
                                            sendBatchToLeadsquared(sapCustomerBatch);
                                            sapCustomerBatch.clear();
                                        }
                                    }
                                }
                            } catch (Exception e) {
                                log.error("processLeadsBulk error creating SAP customer for lead with mobile: {}", phone, e);
                            }
                            success = true;
                        }
                        if (leads.isEmpty()) processedRecords = totalRecords;
                    }
                } else {
                    processedRecords = totalRecords;
                }
            } catch (Exception ee) {
                success = false;
                log.error("processLeadsBulk exception in batch", ee);
            }
            log.info("processLeadsBulk: fetching {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }

        if (!sapCustomerBatch.isEmpty()) {
            sendBatchToLeadsquared(sapCustomerBatch);
            sapCustomerBatch.clear();
        }
        return success;
    }

    @Override
    public void updateLeadInBulk(List<Map<String, String>> sapCustomerList) {
        sendBatchToLeadsquared(sapCustomerList);
    }

    @Override
    public boolean processLeadIds(List<String> leadIds) throws Exception {
        ResponseEntity<Map> response = solarLeadSquaredService.getLeadsInBulkByIds(leadIds);
        boolean success = true;

        if (!response.getStatusCode().is2xxSuccessful() || response.getBody() == null) {
            return false;
        }

        Map<String, Object> responseBody = response.getBody();
        if (!responseBody.containsKey("Leads")) {
            return false;
        }

        List<Map<String, Object>> leads = (List<Map<String, Object>>) responseBody.get("Leads");
        for (Map<String, Object> lead : leads) {
            String prospectStage = (String) lead.getOrDefault("ProspectStage", "");
            String customerCode = (String) lead.getOrDefault("mx_Customer_Code", "");
            try {
                if ("Deal Converted".equals(prospectStage) && (customerCode == null || customerCode.isEmpty())) {
                    LeadSapRequest request = LeadSapRequest.builder()
                            .prospectId(lead.get("ProspectID") != null ? lead.get("ProspectID").toString() : null)
                            .name(lead.get("FirstName") != null ? lead.get("FirstName").toString() : null)
                            .mobile(lead.get("Phone") != null ? lead.get("Phone").toString() : null)
                            .pan(lead.get("mx_PAN_No") != null ? lead.get("mx_PAN_No").toString() : null)
                            .email(lead.get("EmailAddress") != null ? lead.get("EmailAddress").toString() : null)
                            .address(lead.get("mx_Street1") != null ? lead.get("mx_Street1").toString() : null)
                            .city(lead.get("mx_City") != null ? lead.get("mx_City").toString() : null)
                            .state(lead.get("mx_States") != null ? lead.get("mx_States").toString() : null)
                            .pincode(lead.get("mx_Zip") != null ? lead.get("mx_Zip").toString() : null)
                            .build();
                    log.debug("processLeadIds leadData: {}", request);
                    SapCreateResponse sapResponse = sapService.createCustomer(request);
                    if (sapResponse != null && sapResponse.getChangeNumber() != null) {
                        updateLeadInLeadsquared(request.getProspectId(), sapResponse.getChangeNumber());
                    }
                }
            } catch (Exception e) {
                log.error("processLeadIds error creating SAP customer for lead with mobile: {}", lead.get("Phone"), e);
            }
        }
        return success;
    }
}

