package com.integration.configuration;

import com.integration.util.RestUtils;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.client.RestTemplate;

import javax.sql.DataSource;

@Configuration
public class SnowflakeConfig {
    @Bean
    public DataSource snowflakeDataSource(
            @Value("${snowflake.url}") String url,
            @Value("${snowflake.username}") String username,
            @Value("${snowflake.password}") String password,
            @Value("${snowflake.warehouse}") String warehouse,
            @Value("${snowflake.role}") String role) {

        HikariDataSource dataSource = new HikariDataSource();
        dataSource.setJdbcUrl(url);
        dataSource.setUsername(username);
        dataSource.setPassword(password);
        dataSource.setDriverClassName("net.snowflake.client.jdbc.SnowflakeDriver");
        dataSource.addDataSourceProperty("jdbc_use_arrow_result_format", "false");
        dataSource.addDataSourceProperty("warehouse", warehouse);
        dataSource.addDataSourceProperty("role", role);
        dataSource.setMaximumPoolSize(5);
        return dataSource;
    }

    @Bean
    public JdbcTemplate snowflakeJdbcTemplate(DataSource dataSource) {
        return new JdbcTemplate(dataSource);
    }

    @Bean
    public RestTemplate restTemplate(){
        return new RestTemplate();
    }

    @Bean
    public RestUtils restUtils(){
        return new RestUtils();
    }
}

