        verify(solarLeadSquaredService).updateLeadSapCode(eq("prospect-008"), eq("SAP-002"));
        verify(solarLeadSquaredService, never()).updateLeadSapCode(eq("prospect-007"), anyString());
    }

    @Test
    void shouldNotCallUpdateWhenSapResponseHasNoChangeNumber() throws Exception {
        // Arrange — SAP responds successfully but without a Change_Number
        Map<String, Object> lead = buildLead("prospect-009", "Deal Converted", "", "No Code", "9000000003");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));

        Map<String, Object> sapResponseNoCode = new HashMap<>();
        sapResponseNoCode.put("status", 0);
        Map<String, String> record = new HashMap<>();
        // No "Change_Number" key
        sapResponseNoCode.put("Record", record);
        when(sapService.createCustomer(any())).thenReturn(sapResponseNoCode);

        // Act
        solarLeadService.processLeadIds(List.of("prospect-009"));

        // Assert — no update call since no SAP code was returned
        verify(solarLeadSquaredService, never()).updateLeadSapCode(anyString(), anyString());
    }

    // Helper — builds a lead map matching the flat structure returned by getLeadsInBulkByIds
    private Map<String, Object> buildLead(String prospectId, String stage,
                                           String customerCode, String name, String phone) {
        Map<String, Object> lead = new HashMap<>();
        lead.put("ProspectID", prospectId);
        lead.put("ProspectStage", stage);
        lead.put("mx_Customer_Code", customerCode);
        lead.put("FirstName", name);
        lead.put("Phone", phone);
        lead.put("mx_PAN_No", "ABCDE1234F");
        lead.put("EmailAddress", name.toLowerCase().replace(" ", "") + "@example.com");
        lead.put("mx_Street1", "123 Test Street");
        lead.put("mx_City", "Mumbai");
        lead.put("mx_States", "Maharashtra");
        lead.put("mx_Zip", "400001");
        return lead;
    }

    // Helper — builds a SAP success response with a Change_Number
    private Map<String, Object> buildSapSuccessResponse(String changeNumber) {
        Map<String, String> record = new HashMap<>();
        record.put("Change_Number", changeNumber);
        Map<String, Object> response = new HashMap<>();
        response.put("status", 0);
        response.put("Record", record);
        return response;
    }
}

