package com.integration.service.impl;

import com.integration.model.ScheduleConfig;
import com.integration.repository.ScheduleConfigRepository;
import com.integration.service.ScheduleConfigService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class ScheduleConfigServiceImpl implements ScheduleConfigService {

    @Autowired
    ScheduleConfigRepository scheduleConfigRepository;

    @Override
    public void addConfig(ScheduleConfig scheduleConfig) {
        scheduleConfigRepository.save(scheduleConfig);
    }

    @Override
    public String findConfigExpression(String configKey) {
        ScheduleConfig scheduleConfig = scheduleConfigRepository.findByConfigKey(configKey);
        if(scheduleConfig!=null){
            return scheduleConfig.getConfigValue();
        }
        return null;
    }

    @Override
    public List<ScheduleConfig> findActiveConfigs() {
        return scheduleConfigRepository.findAllByActive(true);
    }
}

